async def act(page):
    """Modify the shipping address for order #300 to:
       987 Cedar Court, Los Angeles, CA, 90012

    Plan:
    1. Navigate (relative goto) to the order view for order_id 300.
    2. Open the Shipping Address edit UI by clicking the Edit link scoped to the Shipping Address group when possible.
    3. Fill Street, City, Region/State (select if combobox), and Postcode using accessibility-role selectors scoped to the Shipping Address group where possible.
    4. Click the Save button (make this the final action because it may submit the form / navigate).

    Notes:
    - Use page.get_by_role() and scoped .get_by_role() calls per instructions.
    - Declare the `group` locator up-front so it is always bound.
    - No knowledge_base functions are available in this environment, so none are used.
    """
    # 1) Navigate to the specific order view using a relative URL
    await page.goto('/index.php/admin/sales_order/view/order_id/300/')
    await page.wait_for_load_state('networkidle')

    # Address values to apply
    street_value = "987 Cedar Court"
    city_value = "Los Angeles"
    region_label = "California"  # prefer selecting by label if a combobox exists
    region_value_text = "CA"      # fallback text if no combobox
    postcode_value = "90012"

    # 2) Prepare a scoped locator for the Shipping Address group (always bind it)
    group = page.get_by_role("group", name="Shipping Address")

    # Try to open the Shipping Address edit UI (scoped link first, then fallbacks)
    opened_edit = False
    # Try scoped "Edit" link inside the Shipping Address group
    try:
        if await group.get_by_role("link", name="Edit").count() > 0:
            await group.get_by_role("link", name="Edit").first.click()
            opened_edit = True
    except Exception:
        opened_edit = False

    # Fallbacks if not opened yet
    if not opened_edit:
        try:
            if await page.get_by_role("link", name="Edit Shipping Address").count() > 0:
                await page.get_by_role("link", name="Edit Shipping Address").first.click()
                opened_edit = True
        except Exception:
            opened_edit = False

    if not opened_edit:
        try:
            # Less-scoped Edit link fallback
            if await page.get_by_role("link", name="Edit").count() > 0:
                await page.get_by_role("link", name="Edit").first.click()
                opened_edit = True
        except Exception:
            opened_edit = False

    if not opened_edit:
        raise Exception("Could not open Shipping Address edit UI for order #300")

    # Allow any form/modal to appear
    await page.wait_for_timeout(800)

    # 3) Fill address fields (try scoped to group first, then page-level fallbacks)
    # Street: attempt named textbox, else first textbox in the group
    try:
        if await group.get_by_role("textbox", name="Street Address").count() > 0:
            await group.get_by_role("textbox", name="Street Address").first.fill(street_value)
        else:
            textboxes = group.get_by_role("textbox")
            if await textboxes.count() > 0:
                # fill the first street line
                await textboxes.nth(0).fill(street_value)
    except Exception:
        # try page-level fallbacks
        try:
            if await page.get_by_role("textbox", name="Street Address").count() > 0:
                await page.get_by_role("textbox", name="Street Address").first.fill(street_value)
            else:
                page_textboxes = page.get_by_role("textbox")
                if await page_textboxes.count() > 0:
                    await page_textboxes.nth(0).fill(street_value)
        except Exception:
            pass

    # City
    try:
        if await group.get_by_role("textbox", name="City").count() > 0:
            await group.get_by_role("textbox", name="City").first.fill(city_value)
        else:
            if await page.get_by_role("textbox", name="City").count() > 0:
                await page.get_by_role("textbox", name="City").first.fill(city_value)
    except Exception:
        pass

    # Region / State: prefer combobox selection, otherwise fill textbox
    try:
        if await group.get_by_role("combobox", name="State/Province").count() > 0:
            await group.get_by_role("combobox", name="State/Province").first.select_option(label=region_label)
        elif await group.get_by_role("combobox", name="Region").count() > 0:
            await group.get_by_role("combobox", name="Region").first.select_option(label=region_label)
        elif await group.get_by_role("textbox", name="Region/State").count() > 0:
            await group.get_by_role("textbox", name="Region/State").first.fill(region_value_text)
        else:
            # page-level fallbacks
            if await page.get_by_role("combobox", name="State/Province").count() > 0:
                await page.get_by_role("combobox", name="State/Province").first.select_option(label=region_label)
            elif await page.get_by_role("textbox", name="Region").count() > 0:
                await page.get_by_role("textbox", name="Region").first.fill(region_value_text)
    except Exception:
        pass

    # Postcode / Zip
    try:
        if await group.get_by_role("textbox", name="Zip/Postal Code").count() > 0:
            await group.get_by_role("textbox", name="Zip/Postal Code").first.fill(postcode_value)
        elif await group.get_by_role("textbox", name="Postcode").count() > 0:
            await group.get_by_role("textbox", name="Postcode").first.fill(postcode_value)
        else:
            if await page.get_by_role("textbox", name="Zip/Postal Code").count() > 0:
                await page.get_by_role("textbox", name="Zip/Postal Code").first.fill(postcode_value)
            elif await page.get_by_role("textbox", name="Postcode").count() > 0:
                await page.get_by_role("textbox", name="Postcode").first.fill(postcode_value)
    except Exception:
        pass

    # 4) Save the edited address. This is the final action (may navigate / submit).
    # Try scoped save buttons first (per instruction prefer full get_by_role path)
    try:
        if await group.get_by_role("button", name="Save Address").count() > 0:
            await group.get_by_role("button", name="Save Address").first.click()
            return
    except Exception:
        pass

    try:
        if await group.get_by_role("button", name="Save").count() > 0:
            await group.get_by_role("button", name="Save").first.click()
            return
    except Exception:
        pass

    # Page-level fallbacks for save
    try:
        if await page.get_by_role("button", name="Save Address").count() > 0:
            await page.get_by_role("button", name="Save Address").first.click()
            return
    except Exception:
        pass

    try:
        if await page.get_by_role("button", name="Save").count() > 0:
            await page.get_by_role("button", name="Save").first.click()
            return
    except Exception:
        pass

    try:
        if await page.get_by_role("button", name="Submit").count() > 0:
            await page.get_by_role("button", name="Submit").first.click()
            return
    except Exception:
        pass

    raise Exception("Could not find a Save button to submit the updated shipping address for order #300")
